    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    # Find colors with minimum count (less frequent colors)
    min_count = min(counts.values())
    keep_colors = [c for c, count in counts.items() if count == min_count]

    # Transform grid: keep less frequent colors, convert others to 1
